declare p jsonb := $snapshot_ko_spirit${"version":64,"oldDraft":{"copy":{"spirit.faith.lead":"서울모테트청소년합창단은\n좋은 음악을 향한 태도를 함께 배웁니다.","spirit.community.lead":"합창은 나의 목소리를 더 크게 내는 일이 아니라\n서로의 소리를 듣고 자신의 자리를 조율하며\n함께 하나의 음악을 만드는 공동체 예술입니다.","spirit.lineage.0.body":"작품에 충실한 연주와 교회음악의 깊이를 추구하며\n서울모테트합창단의 음악적 여정이 시작되었습니다.\n이 경험은 다음 세대를 위한 교육으로 이어집니다.","spirit.lineage.1.body":"모테트가 쌓아 온 음악적 경험과 교육철학을\n다음 세대와 나누고자 청소년합창단을 창단했습니다.\n청소년들이 음악을 배우고 함께 성장하는 길을 엽니다.","spirit.lineage.2.body":"매주 정기 연습과 공연, 국내외 교류를 통해\n음악적 기량과 공동체성을 함께 배웁니다.\n연습에서 익힌 태도를 무대와 일상에서 실천합니다.","spirit.lineage.3.body":"서로 다른 문화와 사람을 만나고 이해하며\n더 넓은 세계를 바라보는 시야를 키웁니다.\n음악으로 평화와 미래를 이야기하는 청소년으로 성장합니다.","spirit.learning.0.body":"자신의 소리를 내기 전에\n다른 사람의 호흡과 음색에 귀 기울입니다.\n먼저 듣고 함께 맞추는 태도를 배웁니다.","spirit.learning.0.step":"듣기","spirit.learning.1.body":"음과 리듬을 정확히 익히는 데서 나아가\n가사와 작품의 배경, 작곡가의 뜻을 이해합니다.\n음악이 전하려는 의미를 찾아 표현합니다.","spirit.learning.1.step":"해석하기","spirit.learning.2.body":"각자의 개성을 지우지 않고\n자신의 소리를 이해하며 전체의 균형을 살핍니다.\n공동체 안에서 아름답게 표현하는 법을 배웁니다.","spirit.learning.2.step":"조율하기","spirit.learning.3.body":"정기 연습과 시간, 준비와 무대의 약속을 지킵니다.\n맡은 역할을 성실히 준비하며\n책임감과 서로에 대한 신뢰를 쌓습니다.","spirit.learning.3.step":"약속 지키기","spirit.learning.4.body":"국내외 공연과 문화교류, 나눔의 무대로\n사람과 사람, 서로 다른 문화를 연결합니다.\n음악으로 평화와 희망을 전하는 경험을 나눕니다.","spirit.learning.4.step":"섬기기","spirit.closingCta.text1":"함께 만들어 갈","spirit.closingCta.text4":"참여해 주세요.","spirit.content.cta.body":"입단은 함께 배우고 노래하며 성장하는 시작입니다.\n후원은 청소년의 배움과 성장을 오래 이어 가는 동행입니다.","spirit.faith.paragraph0":"교육은 노래를 무대에 올리는 데서 끝나지 않습니다.\n연습과 공연을 통해 집중과 성실을 익힙니다.","spirit.faith.paragraph1":"악보를 깊이 읽고 작품의 뜻을 이해하며,\n맡은 파트와 무대의 역할에 책임을 다합니다.","spirit.faith.paragraph2":"음악으로 배운 집중과 성실, 배려와 책임이\n일상에서도 좋은 기준으로 이어지도록 돕습니다.","spirit.learning.0.title":"먼저 듣는 사람으로 자랍니다","spirit.learning.1.title":"음악에 담긴 뜻을 배웁니다","spirit.learning.2.title":"공동체 안에서 나의 소리를 찾습니다","spirit.learning.3.title":"한 음과 한 약속을 소중히 여깁니다","spirit.learning.4.title":"음악과 마음을 세상과 나눕니다","spirit.manifesto.label0":"합창의 기본을 배웁니다","spirit.manifesto.label1":"서로 듣는 법을 배웁니다","spirit.manifesto.label2":"무대에서 완성합니다","spirit.manifesto.label3":"삶으로 이어갑니다","spirit.spiritHero.text2":"정신은 말이 아니라","spirit.spiritHero.text3":"이어 온","spirit.spiritHero.text6":"정신은 말이","spirit.spiritHero.text7":"아니라","spirit.spiritHero.text8":"이어 온 ","spirit.spiritHero.text9":"선택","spirit.community.closing":"혼자 부르면 한 사람의 소리입니다.\n서로 듣고 맞추면 화음이 됩니다.\n함께 책임질 때 공동체가 됩니다.","spirit.content.hero.body":"좋은 음악을 향한 태도와 공동체의 가치를\n매주 연습과 공연에서 배우고 이어갑니다.","spirit.spiritHero.text10":"","spirit.spiritHero.text11":"입니다.","spirit.content.motet.body":"서로 다른 음색과 역할을 존중하며\n하나의 작품을 완성합니다.\n각자의 개성을 살리면서 같은 목적을 향해\n함께 나아가는 공동체를 만들어 갑니다.","spirit.faithSection.text1":"음악을","spirit.faithSection.text2":" 대하는 태도가","spirit.faithSection.text3":"다음 세대의","spirit.faithSection.text4":"기준","spirit.faithSection.text5":"이 됩니다.","spirit.motetMeaning.text1":"","spirit.motetMeaning.text2":"서로 다른 ","spirit.motetMeaning.text3":"목소리","spirit.motetMeaning.text4":"가","spirit.motetMeaning.text5":"하나의 음악을","spirit.motetMeaning.text6":"만듭니다.","spirit.content.motet.quote":"전통을 배우고 부르는 데서 나아가\n오늘의 청소년이 삶으로 이어가도록 합니다.","spirit.valuesSection.text6":"네 가지 원칙을 연습과 공연, 공동체에서 함께 지켜갑니다.","spirit.content.values.0.title":"작품에 충실한 음악","spirit.content.values.1.title":"교회음악의 전통과 영성","spirit.content.values.2.title":"함께 부르는 공동체","spirit.content.values.3.title":"다음 세대를 위한 교육","spirit.educationSection.text1":"합창을 통해 경험하는","spirit.educationSection.text5":"듣고 이해하며 함께 조율합니다. 일상의 약속을 지키며 성장합니다.","spirit.content.cta.supportLabel":"후원 안내","spirit.content.manifesto.0.body":"호흡, 발성, 음정, 리듬, 딕션과 앙상블의 기본을 체계적으로 익힙니다.\n자신의 목소리를 이해하고 함께 어울리는 소리의 기초를 세웁니다.","spirit.content.manifesto.1.body":"자신의 소리뿐 아니라 옆 사람과 다른 파트의 소리를 듣습니다.\n서로의 호흡과 음색을 살피며 균형과 조화를 배웁니다.","spirit.content.manifesto.2.body":"연습을 통해 준비한 음악을 공연에서 함께 표현합니다.\n무대에서 맡은 역할을 끝까지 해내며 집중력과 책임감을 경험합니다.","spirit.content.manifesto.3.body":"음악을 대하는 성실함과 공동체 안에서 배운 태도를 삶으로 이어갑니다.\n서로를 존중하고 약속을 지키며 함께 살아가는 힘을 키웁니다.","spirit.content.values.0.summary":"한 음을 소중히 대합니다","spirit.content.values.1.summary":"깊이 듣고 마음을 돌아봅니다","spirit.content.values.2.summary":"우리의 울림을 먼저 듣습니다","spirit.content.values.3.summary":"음악으로 삶을 세웁니다","spirit.content.values.0.description":"악보에 담긴 음과 말, 작곡가의 뜻을 존중합니다.\n한 음을 소중히 읽고 작품의 의미를 이해하며\n자신의 소리로 표현하는 법을 배웁니다.","spirit.content.values.1.description":"찬송과 교회음악의 전통을 통해\n작품에 대한 존중과 절제, 음악의 깊이를 배웁니다.\n음악으로 마음과 삶을 돌아보는 태도를 익힙니다.","spirit.content.values.2.description":"합창은 혼자 완성할 수 없는 예술입니다.\n서로의 호흡과 소리를 듣고 자신의 역할을 조율하며\n배려와 협력으로 하나의 음악을 만듭니다.","spirit.content.values.3.description":"음악적 기량과 함께 성실함과 책임감을 키웁니다.\n타인을 존중하고 서로 다른 문화를 이해하며\n더 넓은 세계를 바라보는 시야를 넓혀 갑니다."},"appearance":{},"deviceCopy":{"mobile":{"spirit.learning.0.body":"서로의 호흡과 음색에 귀 기울이며 먼저 듣고 함께 맞추는 태도를 배웁니다.","spirit.learning.1.body":"가사와 작품의 배경을 이해하고 작곡가의 뜻을 읽으며 음악의 의미를 찾습니다.","spirit.learning.2.body":"개성을 존중하며 균형을 살피고 공동체 안에서 나의 소리를 아름답게 조율합니다.","spirit.learning.3.body":"연습과 무대의 약속을 지키며 맡은 역할을 준비하고 서로의 신뢰를 쌓습니다.","spirit.learning.4.body":"공연과 문화교류, 나눔의 무대로 사람과 문화를 연결하고 평화와 희망을 나눕니다.","spirit.closingCta.text1":"함께 만드는","spirit.content.cta.body":"입단은 함께 성장하는 시작입니다.\n후원은 배움을 이어 가는 동행입니다.\n청소년의 음악적 성장에 함께해 주세요.","spirit.spiritHero.text6":"함께","spirit.spiritHero.text7":"노래하며","spirit.spiritHero.text8":"사랑과 나눔을","spirit.spiritHero.text9":"실천","spirit.spiritHero.text11":"합니다.","spirit.spiritManifesto.text1":"합창에서 ","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다."},"tablet":{"spirit.spiritHero.text6":"함께 ","spirit.spiritHero.text7":"노래하며","spirit.spiritHero.text8":"사랑과 나눔을","spirit.spiritHero.text9":"실천","spirit.spiritHero.text11":"합니다.","spirit.spiritManifesto.text1":"합창에서","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다."},"desktop":{"spirit.closingCta.text1":"함께 만들어 갈","spirit.closingCta.text4":"참여해 주세요.","spirit.spiritHero.text2":"함께 노래하며","spirit.spiritHero.text3":"사랑과 나눔을","spirit.spiritHero.text4":"실천","spirit.spiritHero.text5":"합니다.","spirit.faithSection.text1":"음악을 통해","spirit.faithSection.text2":"","spirit.faithSection.text3":"세대를","spirit.faithSection.text4":"이어","spirit.faithSection.text5":"갑니다.","spirit.spiritHero.english2":"SPIRIT","spirit.valuesSection.text5":"태도","spirit.spiritManifesto.text1":"노래하며","spirit.spiritManifesto.text2":"","spirit.spiritManifesto.text3":"경청과 소통","spirit.spiritManifesto.text4":"을","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다."}},"textStyles":{"desktop":{"spirit.closingCta.text1":{"runs":[{"end":8,"start":0,"style":{"fontSize":50}}],"text":"함께 만들어 갈"},"spirit.closingCta.text4":{"runs":[{"end":8,"start":0,"style":{"fontSize":60,"fontStyle":"normal","fontWeight":700,"textDecoration":"none"}}],"text":"참여해 주세요."},"spirit.spiritHero.text2":{"runs":[{"end":7,"start":0,"style":{"fontSize":60}}],"text":"함께 노래하며"},"spirit.spiritHero.english2":{"runs":[{"end":6,"start":0,"style":{"color":"#fcfaf5","fontStyle":"italic","fontWeight":400,"textDecoration":"none"}}],"text":"SPIRIT"},"spirit.valuesSection.text5":{"runs":[{"end":2,"start":0,"style":{"color":"#ff601a","fontSize":70,"fontStyle":"normal","fontWeight":700}}],"text":"태도"}}},"textLayouts":{"mobile":{"spirit.spiritHero.text8":{"offsetX":-11.5,"offsetY":-7.9},"spirit.spiritHero.text9":{"offsetX":-163.4,"offsetY":33.4},"spirit.spiritHero.text11":{"offsetX":13.2,"offsetY":0},"spirit.spiritManifesto.text2":{"offsetX":-24.5,"offsetY":0},"spirit.spiritManifesto.text3":{"offsetX":-15.2,"offsetY":2.8},"spirit.spiritManifesto.text4":{"offsetX":-16.8,"offsetY":0.5}},"tablet":{"spirit.content.cta.body":{"offsetX":9.7,"offsetY":20.7},"spirit.spiritHero.text6":{"offsetX":0,"offsetY":28.8},"spirit.spiritHero.text7":{"offsetX":50.3,"offsetY":0.2},"spirit.spiritHero.text9":{"offsetX":-187.2,"offsetY":38.2},"spirit.spiritHero.text11":{"offsetX":8.8,"offsetY":0.8},"spirit.spiritManifesto.text1":{"offsetX":-1.1,"offsetY":8},"spirit.spiritManifesto.text2":{"offsetX":174.7,"offsetY":-56.1},"spirit.spiritManifesto.text3":{"offsetX":-185.3,"offsetY":3.6},"spirit.spiritManifesto.text4":{"offsetX":-173.4,"offsetY":0.2},"spirit.spiritManifesto.text5":{"offsetX":-24.5,"offsetY":4}},"desktop":{"spirit.intro.title":{"offsetX":-18.9,"offsetY":27.7},"spirit.closingCta.text1":{"width":74.6,"offsetX":-5.9,"offsetY":15.2},"spirit.closingCta.text2":{"offsetX":41.9,"offsetY":16.4},"spirit.closingCta.text3":{"offsetX":197.3,"offsetY":-31.6},"spirit.closingCta.text4":{"offsetX":-55.1,"offsetY":-12.3},"spirit.spiritHero.text2":{"offsetX":110.1,"offsetY":-27.6},"spirit.spiritHero.text3":{"offsetX":154.8,"offsetY":-31.5},"spirit.spiritHero.text4":{"width":70.8,"offsetX":-0.6,"offsetY":-32.8},"spirit.spiritHero.text5":{"width":73,"offsetX":136,"offsetY":-101.3},"spirit.motetMeaning.text2":{"offsetX":0,"offsetY":34},"spirit.motetMeaning.text3":{"offsetX":5,"offsetY":38.5},"spirit.motetMeaning.text4":{"offsetX":12.6,"offsetY":34},"spirit.motetMeaning.text5":{"offsetX":-11.5,"offsetY":41.5},"spirit.motetMeaning.text6":{"offsetX":2.7,"offsetY":45.3},"spirit.valuesSection.text4":{"offsetX":-87.1,"offsetY":16.4},"spirit.valuesSection.text5":{"offsetX":238.2,"offsetY":-43.2},"spirit.motetMeaning.english2":{"offsetX":20.4,"offsetY":44.6},"spirit.spiritManifesto.text1":{"offsetX":0,"offsetY":17.8},"spirit.spiritManifesto.text2":{"offsetX":142.4,"offsetY":-50.6},"spirit.spiritManifesto.text3":{"offsetX":-35.2,"offsetY":11.4},"spirit.spiritManifesto.text4":{"offsetX":-42.5,"offsetY":5},"spirit.spiritManifesto.text5":{"offsetX":43.3,"offsetY":-1.3},"spirit.heritageTimeline.text2":{"offsetX":43.4,"offsetY":3.8},"spirit.heritageTimeline.text3":{"offsetX":8.3,"offsetY":3.8}}},"schemaVersion":1},"oldPublished":{"copy":{"spirit.faith.lead":"서울모테트청소년합창단은\n좋은 음악을 향한 태도를 함께 배웁니다.","spirit.community.lead":"합창은 나의 목소리를 더 크게 내는 일이 아니라\n서로의 소리를 듣고 자신의 자리를 조율하며\n함께 하나의 음악을 만드는 공동체 예술입니다.","spirit.lineage.0.body":"작품에 충실한 연주와 교회음악의 깊이를 추구하며\n서울모테트합창단의 음악적 여정이 시작되었습니다.\n이 경험은 다음 세대를 위한 교육으로 이어집니다.","spirit.lineage.1.body":"모테트가 쌓아 온 음악적 경험과 교육철학을\n다음 세대와 나누고자 청소년합창단을 창단했습니다.\n청소년들이 음악을 배우고 함께 성장하는 길을 엽니다.","spirit.lineage.2.body":"매주 정기 연습과 공연, 국내외 교류를 통해\n음악적 기량과 공동체성을 함께 배웁니다.\n연습에서 익힌 태도를 무대와 일상에서 실천합니다.","spirit.lineage.3.body":"서로 다른 문화와 사람을 만나고 이해하며\n더 넓은 세계를 바라보는 시야를 키웁니다.\n음악으로 평화와 미래를 이야기하는 청소년으로 성장합니다.","spirit.learning.0.body":"자신의 소리를 내기 전에\n다른 사람의 호흡과 음색에 귀 기울입니다.\n먼저 듣고 함께 맞추는 태도를 배웁니다.","spirit.learning.0.step":"듣기","spirit.learning.1.body":"음과 리듬을 정확히 익히는 데서 나아가\n가사와 작품의 배경, 작곡가의 뜻을 이해합니다.\n음악이 전하려는 의미를 찾아 표현합니다.","spirit.learning.1.step":"해석하기","spirit.learning.2.body":"각자의 개성을 지우지 않고\n자신의 소리를 이해하며 전체의 균형을 살핍니다.\n공동체 안에서 아름답게 표현하는 법을 배웁니다.","spirit.learning.2.step":"조율하기","spirit.learning.3.body":"정기 연습과 시간, 준비와 무대의 약속을 지킵니다.\n맡은 역할을 성실히 준비하며\n책임감과 서로에 대한 신뢰를 쌓습니다.","spirit.learning.3.step":"약속 지키기","spirit.learning.4.body":"국내외 공연과 문화교류, 나눔의 무대로\n사람과 사람, 서로 다른 문화를 연결합니다.\n음악으로 평화와 희망을 전하는 경험을 나눕니다.","spirit.learning.4.step":"섬기기","spirit.closingCta.text1":"함께 만들어 갈","spirit.closingCta.text4":"참여해 주세요.","spirit.content.cta.body":"입단은 함께 배우고 노래하며 성장하는 시작입니다.\n후원은 청소년의 배움과 성장을 오래 이어 가는 동행입니다.","spirit.faith.paragraph0":"교육은 노래를 무대에 올리는 데서 끝나지 않습니다.\n연습과 공연을 통해 집중과 성실을 익힙니다.","spirit.faith.paragraph1":"악보를 깊이 읽고 작품의 뜻을 이해하며,\n맡은 파트와 무대의 역할에 책임을 다합니다.","spirit.faith.paragraph2":"음악으로 배운 집중과 성실, 배려와 책임이\n일상에서도 좋은 기준으로 이어지도록 돕습니다.","spirit.learning.0.title":"먼저 듣는 사람으로 자랍니다","spirit.learning.1.title":"음악에 담긴 뜻을 배웁니다","spirit.learning.2.title":"공동체 안에서 나의 소리를 찾습니다","spirit.learning.3.title":"한 음과 한 약속을 소중히 여깁니다","spirit.learning.4.title":"음악과 마음을 세상과 나눕니다","spirit.manifesto.label0":"합창의 기본을 배웁니다","spirit.manifesto.label1":"서로 듣는 법을 배웁니다","spirit.manifesto.label2":"무대에서 완성합니다","spirit.manifesto.label3":"삶으로 이어갑니다","spirit.spiritHero.text2":"정신은 말이 아니라","spirit.spiritHero.text3":"이어 온","spirit.spiritHero.text6":"정신은 말이","spirit.spiritHero.text7":"아니라","spirit.spiritHero.text8":"이어 온 ","spirit.spiritHero.text9":"선택","spirit.community.closing":"혼자 부르면 한 사람의 소리입니다.\n서로 듣고 맞추면 화음이 됩니다.\n함께 책임질 때 공동체가 됩니다.","spirit.content.hero.body":"좋은 음악을 향한 태도와 공동체의 가치를\n매주 연습과 공연에서 배우고 이어갑니다.","spirit.spiritHero.text10":"","spirit.spiritHero.text11":"입니다.","spirit.content.motet.body":"서로 다른 음색과 역할을 존중하며\n하나의 작품을 완성합니다.\n각자의 개성을 살리면서 같은 목적을 향해\n함께 나아가는 공동체를 만들어 갑니다.","spirit.faithSection.text1":"음악을","spirit.faithSection.text2":" 대하는 태도가","spirit.faithSection.text3":"다음 세대의","spirit.faithSection.text4":"기준","spirit.faithSection.text5":"이 됩니다.","spirit.motetMeaning.text1":"","spirit.motetMeaning.text2":"서로 다른 ","spirit.motetMeaning.text3":"목소리","spirit.motetMeaning.text4":"가","spirit.motetMeaning.text5":"하나의 음악을","spirit.motetMeaning.text6":"만듭니다.","spirit.content.motet.quote":"전통을 배우고 부르는 데서 나아가\n오늘의 청소년이 삶으로 이어가도록 합니다.","spirit.valuesSection.text6":"네 가지 원칙을 연습과 공연, 공동체에서 함께 지켜갑니다.","spirit.content.values.0.title":"작품에 충실한 음악","spirit.content.values.1.title":"교회음악의 전통과 영성","spirit.content.values.2.title":"함께 부르는 공동체","spirit.content.values.3.title":"다음 세대를 위한 교육","spirit.educationSection.text1":"합창을 통해 경험하는","spirit.educationSection.text5":"듣고 이해하며 함께 조율합니다. 일상의 약속을 지키며 성장합니다.","spirit.content.cta.supportLabel":"후원 안내","spirit.content.manifesto.0.body":"호흡, 발성, 음정, 리듬, 딕션과 앙상블의 기본을 체계적으로 익힙니다.\n자신의 목소리를 이해하고 함께 어울리는 소리의 기초를 세웁니다.","spirit.content.manifesto.1.body":"자신의 소리뿐 아니라 옆 사람과 다른 파트의 소리를 듣습니다.\n서로의 호흡과 음색을 살피며 균형과 조화를 배웁니다.","spirit.content.manifesto.2.body":"연습을 통해 준비한 음악을 공연에서 함께 표현합니다.\n무대에서 맡은 역할을 끝까지 해내며 집중력과 책임감을 경험합니다.","spirit.content.manifesto.3.body":"음악을 대하는 성실함과 공동체 안에서 배운 태도를 삶으로 이어갑니다.\n서로를 존중하고 약속을 지키며 함께 살아가는 힘을 키웁니다.","spirit.content.values.0.summary":"한 음을 소중히 대합니다","spirit.content.values.1.summary":"깊이 듣고 마음을 돌아봅니다","spirit.content.values.2.summary":"우리의 울림을 먼저 듣습니다","spirit.content.values.3.summary":"음악으로 삶을 세웁니다","spirit.content.values.0.description":"악보에 담긴 음과 말, 작곡가의 뜻을 존중합니다.\n한 음을 소중히 읽고 작품의 의미를 이해하며\n자신의 소리로 표현하는 법을 배웁니다.","spirit.content.values.1.description":"찬송과 교회음악의 전통을 통해\n작품에 대한 존중과 절제, 음악의 깊이를 배웁니다.\n음악으로 마음과 삶을 돌아보는 태도를 익힙니다.","spirit.content.values.2.description":"합창은 혼자 완성할 수 없는 예술입니다.\n서로의 호흡과 소리를 듣고 자신의 역할을 조율하며\n배려와 협력으로 하나의 음악을 만듭니다.","spirit.content.values.3.description":"음악적 기량과 함께 성실함과 책임감을 키웁니다.\n타인을 존중하고 서로 다른 문화를 이해하며\n더 넓은 세계를 바라보는 시야를 넓혀 갑니다."},"appearance":{},"deviceCopy":{"mobile":{"spirit.learning.0.body":"서로의 호흡과 음색에 귀 기울이며 먼저 듣고 함께 맞추는 태도를 배웁니다.","spirit.learning.1.body":"가사와 작품의 배경을 이해하고 작곡가의 뜻을 읽으며 음악의 의미를 찾습니다.","spirit.learning.2.body":"개성을 존중하며 균형을 살피고 공동체 안에서 나의 소리를 아름답게 조율합니다.","spirit.learning.3.body":"연습과 무대의 약속을 지키며 맡은 역할을 준비하고 서로의 신뢰를 쌓습니다.","spirit.learning.4.body":"공연과 문화교류, 나눔의 무대로 사람과 문화를 연결하고 평화와 희망을 나눕니다.","spirit.closingCta.text1":"함께 만드는","spirit.content.cta.body":"입단은 함께 성장하는 시작입니다.\n후원은 배움을 이어 가는 동행입니다.\n청소년의 음악적 성장에 함께해 주세요.","spirit.spiritHero.text6":"함께","spirit.spiritHero.text7":"노래하며","spirit.spiritHero.text8":"사랑과 나눔을","spirit.spiritHero.text9":"실천","spirit.spiritHero.text11":"합니다.","spirit.spiritManifesto.text1":"합창에서 ","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다."},"tablet":{"spirit.spiritHero.text6":"함께 ","spirit.spiritHero.text7":"노래하며","spirit.spiritHero.text8":"사랑과 나눔을","spirit.spiritHero.text9":"실천","spirit.spiritHero.text11":"합니다.","spirit.spiritManifesto.text1":"합창에서","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다."},"desktop":{"spirit.closingCta.text1":"함께 만들어 갈","spirit.closingCta.text4":"참여해 주세요.","spirit.spiritHero.text2":"함께 노래하며","spirit.spiritHero.text3":"사랑과 나눔을","spirit.spiritHero.text4":"실천","spirit.spiritHero.text5":"합니다.","spirit.faithSection.text1":"음악을 통해","spirit.faithSection.text2":"","spirit.faithSection.text3":"세대를","spirit.faithSection.text4":"이어","spirit.faithSection.text5":"갑니다.","spirit.spiritHero.english2":"SPIRIT","spirit.valuesSection.text5":"태도","spirit.spiritManifesto.text1":"노래하며","spirit.spiritManifesto.text2":"","spirit.spiritManifesto.text3":"경청과 소통","spirit.spiritManifesto.text4":"을","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다."}},"textStyles":{"desktop":{"spirit.closingCta.text1":{"runs":[{"end":8,"start":0,"style":{"fontSize":50}}],"text":"함께 만들어 갈"},"spirit.closingCta.text4":{"runs":[{"end":8,"start":0,"style":{"fontSize":60,"fontStyle":"normal","fontWeight":700,"textDecoration":"none"}}],"text":"참여해 주세요."},"spirit.spiritHero.text2":{"runs":[{"end":7,"start":0,"style":{"fontSize":60}}],"text":"함께 노래하며"},"spirit.spiritHero.english2":{"runs":[{"end":6,"start":0,"style":{"color":"#fcfaf5","fontStyle":"italic","fontWeight":400,"textDecoration":"none"}}],"text":"SPIRIT"},"spirit.valuesSection.text5":{"runs":[{"end":2,"start":0,"style":{"color":"#ff601a","fontSize":70,"fontStyle":"normal","fontWeight":700}}],"text":"태도"}}},"textLayouts":{"mobile":{"spirit.spiritHero.text8":{"offsetX":-11.5,"offsetY":-7.9},"spirit.spiritHero.text9":{"offsetX":-163.4,"offsetY":33.4},"spirit.spiritHero.text11":{"offsetX":13.2,"offsetY":0},"spirit.spiritManifesto.text2":{"offsetX":-24.5,"offsetY":0},"spirit.spiritManifesto.text3":{"offsetX":-15.2,"offsetY":2.8},"spirit.spiritManifesto.text4":{"offsetX":-16.8,"offsetY":0.5}},"tablet":{"spirit.content.cta.body":{"offsetX":9.7,"offsetY":20.7},"spirit.spiritHero.text6":{"offsetX":0,"offsetY":28.8},"spirit.spiritHero.text7":{"offsetX":50.3,"offsetY":0.2},"spirit.spiritHero.text9":{"offsetX":-187.2,"offsetY":38.2},"spirit.spiritHero.text11":{"offsetX":8.8,"offsetY":0.8},"spirit.spiritManifesto.text1":{"offsetX":-1.1,"offsetY":8},"spirit.spiritManifesto.text2":{"offsetX":174.7,"offsetY":-56.1},"spirit.spiritManifesto.text3":{"offsetX":-185.3,"offsetY":3.6},"spirit.spiritManifesto.text4":{"offsetX":-173.4,"offsetY":0.2},"spirit.spiritManifesto.text5":{"offsetX":-24.5,"offsetY":4}},"desktop":{"spirit.intro.title":{"offsetX":-18.9,"offsetY":27.7},"spirit.closingCta.text1":{"width":74.6,"offsetX":-5.9,"offsetY":15.2},"spirit.closingCta.text2":{"offsetX":41.9,"offsetY":16.4},"spirit.closingCta.text3":{"offsetX":197.3,"offsetY":-31.6},"spirit.closingCta.text4":{"offsetX":-55.1,"offsetY":-12.3},"spirit.spiritHero.text2":{"offsetX":110.1,"offsetY":-27.6},"spirit.spiritHero.text3":{"offsetX":154.8,"offsetY":-31.5},"spirit.spiritHero.text4":{"width":70.8,"offsetX":-0.6,"offsetY":-32.8},"spirit.spiritHero.text5":{"width":73,"offsetX":136,"offsetY":-101.3},"spirit.motetMeaning.text2":{"offsetX":0,"offsetY":34},"spirit.motetMeaning.text3":{"offsetX":5,"offsetY":38.5},"spirit.motetMeaning.text4":{"offsetX":12.6,"offsetY":34},"spirit.motetMeaning.text5":{"offsetX":-11.5,"offsetY":41.5},"spirit.motetMeaning.text6":{"offsetX":2.7,"offsetY":45.3},"spirit.valuesSection.text4":{"offsetX":-87.1,"offsetY":16.4},"spirit.valuesSection.text5":{"offsetX":238.2,"offsetY":-43.2},"spirit.motetMeaning.english2":{"offsetX":20.4,"offsetY":44.6},"spirit.spiritManifesto.text1":{"offsetX":0,"offsetY":17.8},"spirit.spiritManifesto.text2":{"offsetX":142.4,"offsetY":-50.6},"spirit.spiritManifesto.text3":{"offsetX":-35.2,"offsetY":11.4},"spirit.spiritManifesto.text4":{"offsetX":-42.5,"offsetY":5},"spirit.spiritManifesto.text5":{"offsetX":43.3,"offsetY":-1.3},"spirit.heritageTimeline.text2":{"offsetX":43.4,"offsetY":3.8},"spirit.heritageTimeline.text3":{"offsetX":8.3,"offsetY":3.8}}},"schemaVersion":1},"next":{"copy":{"spirit.faith.lead":"서울모테트청소년합창단은\n좋은 음악을 향한 태도를 함께 배웁니다.","spirit.community.lead":"합창은 나의 목소리를 더 크게 내는 일이 아니라\n서로의 소리를 듣고 자신의 자리를 조율하며\n함께 하나의 음악을 만드는 공동체 예술입니다.","spirit.lineage.0.body":"작품에 충실한 연주와 교회음악의 깊이를 추구하며\n서울모테트합창단의 음악적 여정이 시작되었습니다.\n이 경험은 다음 세대를 위한 교육으로 이어집니다.","spirit.lineage.1.body":"모테트가 쌓아 온 음악적 경험과 교육철학을\n다음 세대와 나누고자 청소년합창단을 창단했습니다.\n청소년들이 음악을 배우고 함께 성장하는 길을 엽니다.","spirit.lineage.2.body":"매주 정기 연습과 공연, 국내외 교류를 통해\n음악적 기량과 공동체성을 함께 배웁니다.\n연습에서 익힌 태도를 무대와 일상에서 실천합니다.","spirit.lineage.3.body":"서로 다른 문화와 사람을 만나고 이해하며\n더 넓은 세계를 바라보는 시야를 키웁니다.\n음악으로 평화와 미래를 이야기하는 청소년으로 성장합니다.","spirit.learning.0.body":"자신의 소리를 내기 전에\n다른 사람의 호흡과 음색에 귀 기울입니다.\n먼저 듣고 함께 맞추는 태도를 배웁니다.","spirit.learning.0.step":"듣기","spirit.learning.1.body":"음과 리듬을 정확히 익히는 데서 나아가\n가사와 작품의 배경, 작곡가의 뜻을 이해합니다.\n음악이 전하려는 의미를 찾아 표현합니다.","spirit.learning.1.step":"해석하기","spirit.learning.2.body":"각자의 개성을 지우지 않고\n자신의 소리를 이해하며 전체의 균형을 살핍니다.\n공동체 안에서 아름답게 표현하는 법을 배웁니다.","spirit.learning.2.step":"조율하기","spirit.learning.3.body":"정기 연습과 시간, 준비와 무대의 약속을 지킵니다.\n맡은 역할을 성실히 준비하며\n책임감과 서로에 대한 신뢰를 쌓습니다.","spirit.learning.3.step":"약속 지키기","spirit.learning.4.body":"국내외 공연과 문화교류, 나눔의 무대로\n사람과 사람, 서로 다른 문화를 연결합니다.\n음악으로 평화와 희망을 전하는 경험을 나눕니다.","spirit.learning.4.step":"섬기기","spirit.closingCta.text1":"함께 만들어 갈","spirit.closingCta.text4":"참여해 주세요.","spirit.content.cta.body":"입단은 함께 배우고 노래하며 성장하는 시작입니다.\n후원은 청소년의 배움과 성장을 오래 이어 가는 동행입니다.","spirit.faith.paragraph0":"교육은 노래를 무대에 올리는 데서 끝나지 않습니다.\n연습과 공연을 통해 집중과 성실을 익힙니다.","spirit.faith.paragraph1":"악보를 깊이 읽고 작품의 뜻을 이해하며,\n맡은 파트와 무대의 역할에 책임을 다합니다.","spirit.faith.paragraph2":"음악으로 배운 집중과 성실, 배려와 책임이\n일상에서도 좋은 기준으로 이어지도록 돕습니다.","spirit.learning.0.title":"먼저 듣는 사람으로 자랍니다","spirit.learning.1.title":"음악에 담긴 뜻을 배웁니다","spirit.learning.2.title":"공동체 안에서 나의 소리를 찾습니다","spirit.learning.3.title":"한 음과 한 약속을 소중히 여깁니다","spirit.learning.4.title":"음악과 마음을 세상과 나눕니다","spirit.manifesto.label0":"합창의 기본을 배웁니다","spirit.manifesto.label1":"서로 듣는 법을 배웁니다","spirit.manifesto.label2":"무대에서 완성합니다","spirit.manifesto.label3":"삶으로 이어갑니다","spirit.spiritHero.text2":"정신은 말이 아니라","spirit.spiritHero.text3":"이어 온","spirit.spiritHero.text6":"정신은 말이","spirit.spiritHero.text7":"아니라","spirit.spiritHero.text8":"이어 온 ","spirit.spiritHero.text9":"선택","spirit.community.closing":"혼자 부르면 한 사람의 소리입니다.\n서로 듣고 맞추면 화음이 됩니다.\n함께 책임질 때 공동체가 됩니다.","spirit.content.hero.body":"좋은 음악을 향한 태도와 공동체의 가치를\n매주 연습과 공연에서 배우고 이어갑니다.","spirit.spiritHero.text10":"","spirit.spiritHero.text11":"입니다.","spirit.content.motet.body":"서로 다른 음색과 역할을 존중하며\n하나의 작품을 완성합니다.\n각자의 개성을 살리면서 같은 목적을 향해\n함께 나아가는 공동체를 만들어 갑니다.","spirit.faithSection.text1":"음악을","spirit.faithSection.text2":" 대하는 태도가","spirit.faithSection.text3":"다음 세대의","spirit.faithSection.text4":"기준","spirit.faithSection.text5":"이 됩니다.","spirit.motetMeaning.text1":"","spirit.motetMeaning.text2":"서로 다른 ","spirit.motetMeaning.text3":"목소리","spirit.motetMeaning.text4":"가","spirit.motetMeaning.text5":"하나의 음악을","spirit.motetMeaning.text6":"만듭니다.","spirit.content.motet.quote":"전통을 배우고 부르는 데서 나아가\n오늘의 청소년이 삶으로 이어가도록 합니다.","spirit.valuesSection.text6":"네 가지 원칙을 연습과 공연, 공동체에서 함께 지켜갑니다.","spirit.content.values.0.title":"작품에 충실한 음악","spirit.content.values.1.title":"교회음악의 전통과 영성","spirit.content.values.2.title":"함께 부르는 공동체","spirit.content.values.3.title":"다음 세대를 위한 교육","spirit.educationSection.text1":"합창을 통해 경험하는","spirit.educationSection.text5":"듣고 이해하며 함께 조율합니다. 일상의 약속을 지키며 성장합니다.","spirit.content.cta.supportLabel":"후원 안내","spirit.content.manifesto.0.body":"호흡, 발성, 음정, 리듬, 딕션과 앙상블의 기본을 체계적으로 익힙니다.\n자신의 목소리를 이해하고 함께 어울리는 소리의 기초를 세웁니다.","spirit.content.manifesto.1.body":"자신의 소리뿐 아니라 옆 사람과 다른 파트의 소리를 듣습니다.\n서로의 호흡과 음색을 살피며 균형과 조화를 배웁니다.","spirit.content.manifesto.2.body":"연습을 통해 준비한 음악을 공연에서 함께 표현합니다.\n무대에서 맡은 역할을 끝까지 해내며 집중력과 책임감을 경험합니다.","spirit.content.manifesto.3.body":"음악을 대하는 성실함과 공동체 안에서 배운 태도를 삶으로 이어갑니다.\n서로를 존중하고 약속을 지키며 함께 살아가는 힘을 키웁니다.","spirit.content.values.0.summary":"한 음을 소중히 대합니다","spirit.content.values.1.summary":"깊이 듣고 마음을 돌아봅니다","spirit.content.values.2.summary":"우리의 울림을 먼저 듣습니다","spirit.content.values.3.summary":"음악으로 삶을 세웁니다","spirit.content.values.0.description":"악보에 담긴 음과 말, 작곡가의 뜻을 존중합니다.\n한 음을 소중히 읽고 작품의 의미를 이해하며\n자신의 소리로 표현하는 법을 배웁니다.","spirit.content.values.1.description":"찬송과 교회음악의 전통을 통해\n작품에 대한 존중과 절제, 음악의 깊이를 배웁니다.\n음악으로 마음과 삶을 돌아보는 태도를 익힙니다.","spirit.content.values.2.description":"합창은 혼자 완성할 수 없는 예술입니다.\n서로의 호흡과 소리를 듣고 자신의 역할을 조율하며\n배려와 협력으로 하나의 음악을 만듭니다.","spirit.content.values.3.description":"음악적 기량과 함께 성실함과 책임감을 키웁니다.\n타인을 존중하고 서로 다른 문화를 이해하며\n더 넓은 세계를 바라보는 시야를 넓혀 갑니다."},"appearance":{},"deviceCopy":{"mobile":{"spirit.learning.0.body":"자신의 소리를 내기 전에\n다른 사람의 호흡과 음색에 귀 기울입니다.\n먼저 듣고 함께 맞추는 태도를 배웁니다.","spirit.learning.1.body":"음과 리듬을 정확히 익히는 데서 나아가\n가사와 작품의 배경, 작곡가의 뜻을 이해합니다.\n음악이 전하려는 의미를 찾아 표현합니다.","spirit.learning.2.body":"각자의 개성을 지우지 않고\n자신의 소리를 이해하며 전체의 균형을 살핍니다.\n공동체 안에서 아름답게 표현하는 법을 배웁니다.","spirit.learning.3.body":"정기 연습과 시간, 준비와 무대의 약속을 지킵니다.\n맡은 역할을 성실히 준비하며\n책임감과 서로에 대한 신뢰를 쌓습니다.","spirit.learning.4.body":"국내외 공연과 문화교류, 나눔의 무대로\n사람과 사람, 서로 다른 문화를 연결합니다.\n음악으로 평화와 희망을 전하는 경험을 나눕니다.","spirit.closingCta.text1":"함께 만들어 갈","spirit.content.cta.body":"입단은 함께 배우고 노래하며 성장하는 시작입니다.\n후원은 청소년의 배움과 성장을 오래 이어 가는 동행입니다.","spirit.spiritHero.text6":"함께","spirit.spiritHero.text7":"노래하며","spirit.spiritHero.text8":"사랑과 나눔을","spirit.spiritHero.text9":"실천","spirit.spiritHero.text11":"합니다.","spirit.spiritManifesto.text1":"노래하며","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다.","spirit.faith.lead":"서울모테트청소년합창단은\n좋은 음악을 향한 태도를 함께 배웁니다.","spirit.community.lead":"합창은 나의 목소리를 더 크게 내는 일이 아니라\n서로의 소리를 듣고 자신의 자리를 조율하며\n함께 하나의 음악을 만드는 공동체 예술입니다.","spirit.lineage.0.body":"작품에 충실한 연주와 교회음악의 깊이를 추구하며\n서울모테트합창단의 음악적 여정이 시작되었습니다.\n이 경험은 다음 세대를 위한 교육으로 이어집니다.","spirit.lineage.1.body":"모테트가 쌓아 온 음악적 경험과 교육철학을\n다음 세대와 나누고자 청소년합창단을 창단했습니다.\n청소년들이 음악을 배우고 함께 성장하는 길을 엽니다.","spirit.lineage.2.body":"매주 정기 연습과 공연, 국내외 교류를 통해\n음악적 기량과 공동체성을 함께 배웁니다.\n연습에서 익힌 태도를 무대와 일상에서 실천합니다.","spirit.lineage.3.body":"서로 다른 문화와 사람을 만나고 이해하며\n더 넓은 세계를 바라보는 시야를 키웁니다.\n음악으로 평화와 미래를 이야기하는 청소년으로 성장합니다.","spirit.learning.0.step":"듣기","spirit.learning.1.step":"해석하기","spirit.learning.2.step":"조율하기","spirit.learning.3.step":"약속 지키기","spirit.learning.4.step":"섬기기","spirit.closingCta.text4":"참여해 주세요.","spirit.faith.paragraph0":"교육은 노래를 무대에 올리는 데서 끝나지 않습니다.\n연습과 공연을 통해 집중과 성실을 익힙니다.","spirit.faith.paragraph1":"악보를 깊이 읽고 작품의 뜻을 이해하며,\n맡은 파트와 무대의 역할에 책임을 다합니다.","spirit.faith.paragraph2":"음악으로 배운 집중과 성실, 배려와 책임이\n일상에서도 좋은 기준으로 이어지도록 돕습니다.","spirit.learning.0.title":"먼저 듣는 사람으로 자랍니다","spirit.learning.1.title":"음악에 담긴 뜻을 배웁니다","spirit.learning.2.title":"공동체 안에서 나의 소리를 찾습니다","spirit.learning.3.title":"한 음과 한 약속을 소중히 여깁니다","spirit.learning.4.title":"음악과 마음을 세상과 나눕니다","spirit.manifesto.label0":"합창의 기본을 배웁니다","spirit.manifesto.label1":"서로 듣는 법을 배웁니다","spirit.manifesto.label2":"무대에서 완성합니다","spirit.manifesto.label3":"삶으로 이어갑니다","spirit.spiritHero.text2":"함께 노래하며","spirit.spiritHero.text3":"사랑과 나눔을","spirit.community.closing":"혼자 부르면 한 사람의 소리입니다.\n서로 듣고 맞추면 화음이 됩니다.\n함께 책임질 때 공동체가 됩니다.","spirit.content.hero.body":"좋은 음악을 향한 태도와 공동체의 가치를\n매주 연습과 공연에서 배우고 이어갑니다.","spirit.spiritHero.text10":"","spirit.content.motet.body":"서로 다른 음색과 역할을 존중하며\n하나의 작품을 완성합니다.\n각자의 개성을 살리면서 같은 목적을 향해\n함께 나아가는 공동체를 만들어 갑니다.","spirit.faithSection.text1":"음악을 통해","spirit.faithSection.text2":"","spirit.faithSection.text3":"세대를","spirit.faithSection.text4":"이어","spirit.faithSection.text5":"갑니다.","spirit.motetMeaning.text1":"","spirit.motetMeaning.text2":"서로 다른 ","spirit.motetMeaning.text3":"목소리","spirit.motetMeaning.text4":"가","spirit.motetMeaning.text5":"하나의 음악을","spirit.motetMeaning.text6":"만듭니다.","spirit.content.motet.quote":"전통을 배우고 부르는 데서 나아가\n오늘의 청소년이 삶으로 이어가도록 합니다.","spirit.valuesSection.text6":"네 가지 원칙을 연습과 공연, 공동체에서 함께 지켜갑니다.","spirit.content.values.0.title":"작품에 충실한 음악","spirit.content.values.1.title":"교회음악의 전통과 영성","spirit.content.values.2.title":"함께 부르는 공동체","spirit.content.values.3.title":"다음 세대를 위한 교육","spirit.educationSection.text1":"합창을 통해 경험하는","spirit.educationSection.text5":"듣고 이해하며 함께 조율합니다. 일상의 약속을 지키며 성장합니다.","spirit.content.cta.supportLabel":"후원 안내","spirit.content.manifesto.0.body":"호흡, 발성, 음정, 리듬, 딕션과 앙상블의 기본을 체계적으로 익힙니다.\n자신의 목소리를 이해하고 함께 어울리는 소리의 기초를 세웁니다.","spirit.content.manifesto.1.body":"자신의 소리뿐 아니라 옆 사람과 다른 파트의 소리를 듣습니다.\n서로의 호흡과 음색을 살피며 균형과 조화를 배웁니다.","spirit.content.manifesto.2.body":"연습을 통해 준비한 음악을 공연에서 함께 표현합니다.\n무대에서 맡은 역할을 끝까지 해내며 집중력과 책임감을 경험합니다.","spirit.content.manifesto.3.body":"음악을 대하는 성실함과 공동체 안에서 배운 태도를 삶으로 이어갑니다.\n서로를 존중하고 약속을 지키며 함께 살아가는 힘을 키웁니다.","spirit.content.values.0.summary":"한 음을 소중히 대합니다","spirit.content.values.1.summary":"깊이 듣고 마음을 돌아봅니다","spirit.content.values.2.summary":"우리의 울림을 먼저 듣습니다","spirit.content.values.3.summary":"음악으로 삶을 세웁니다","spirit.content.values.0.description":"악보에 담긴 음과 말, 작곡가의 뜻을 존중합니다.\n한 음을 소중히 읽고 작품의 의미를 이해하며\n자신의 소리로 표현하는 법을 배웁니다.","spirit.content.values.1.description":"찬송과 교회음악의 전통을 통해\n작품에 대한 존중과 절제, 음악의 깊이를 배웁니다.\n음악으로 마음과 삶을 돌아보는 태도를 익힙니다.","spirit.content.values.2.description":"합창은 혼자 완성할 수 없는 예술입니다.\n서로의 호흡과 소리를 듣고 자신의 역할을 조율하며\n배려와 협력으로 하나의 음악을 만듭니다.","spirit.content.values.3.description":"음악적 기량과 함께 성실함과 책임감을 키웁니다.\n타인을 존중하고 서로 다른 문화를 이해하며\n더 넓은 세계를 바라보는 시야를 넓혀 갑니다.","spirit.spiritHero.text4":"실천","spirit.spiritHero.text5":"합니다.","spirit.spiritHero.english2":"SPIRIT","spirit.valuesSection.text5":"태도","spirit.spiritManifesto.text2":"","spirit.spiritManifesto.text3":"경청과 소통","spirit.spiritManifesto.text4":"을"},"tablet":{"spirit.spiritHero.text6":"함께","spirit.spiritHero.text7":"노래하며","spirit.spiritHero.text8":"사랑과 나눔을","spirit.spiritHero.text9":"실천","spirit.spiritHero.text11":"합니다.","spirit.spiritManifesto.text1":"노래하며","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다.","spirit.faith.lead":"서울모테트청소년합창단은\n좋은 음악을 향한 태도를 함께 배웁니다.","spirit.community.lead":"합창은 나의 목소리를 더 크게 내는 일이 아니라\n서로의 소리를 듣고 자신의 자리를 조율하며\n함께 하나의 음악을 만드는 공동체 예술입니다.","spirit.lineage.0.body":"작품에 충실한 연주와 교회음악의 깊이를 추구하며\n서울모테트합창단의 음악적 여정이 시작되었습니다.\n이 경험은 다음 세대를 위한 교육으로 이어집니다.","spirit.lineage.1.body":"모테트가 쌓아 온 음악적 경험과 교육철학을\n다음 세대와 나누고자 청소년합창단을 창단했습니다.\n청소년들이 음악을 배우고 함께 성장하는 길을 엽니다.","spirit.lineage.2.body":"매주 정기 연습과 공연, 국내외 교류를 통해\n음악적 기량과 공동체성을 함께 배웁니다.\n연습에서 익힌 태도를 무대와 일상에서 실천합니다.","spirit.lineage.3.body":"서로 다른 문화와 사람을 만나고 이해하며\n더 넓은 세계를 바라보는 시야를 키웁니다.\n음악으로 평화와 미래를 이야기하는 청소년으로 성장합니다.","spirit.learning.0.body":"자신의 소리를 내기 전에\n다른 사람의 호흡과 음색에 귀 기울입니다.\n먼저 듣고 함께 맞추는 태도를 배웁니다.","spirit.learning.0.step":"듣기","spirit.learning.1.body":"음과 리듬을 정확히 익히는 데서 나아가\n가사와 작품의 배경, 작곡가의 뜻을 이해합니다.\n음악이 전하려는 의미를 찾아 표현합니다.","spirit.learning.1.step":"해석하기","spirit.learning.2.body":"각자의 개성을 지우지 않고\n자신의 소리를 이해하며 전체의 균형을 살핍니다.\n공동체 안에서 아름답게 표현하는 법을 배웁니다.","spirit.learning.2.step":"조율하기","spirit.learning.3.body":"정기 연습과 시간, 준비와 무대의 약속을 지킵니다.\n맡은 역할을 성실히 준비하며\n책임감과 서로에 대한 신뢰를 쌓습니다.","spirit.learning.3.step":"약속 지키기","spirit.learning.4.body":"국내외 공연과 문화교류, 나눔의 무대로\n사람과 사람, 서로 다른 문화를 연결합니다.\n음악으로 평화와 희망을 전하는 경험을 나눕니다.","spirit.learning.4.step":"섬기기","spirit.closingCta.text1":"함께 만들어 갈","spirit.closingCta.text4":"참여해 주세요.","spirit.content.cta.body":"입단은 함께 배우고 노래하며 성장하는 시작입니다.\n후원은 청소년의 배움과 성장을 오래 이어 가는 동행입니다.","spirit.faith.paragraph0":"교육은 노래를 무대에 올리는 데서 끝나지 않습니다.\n연습과 공연을 통해 집중과 성실을 익힙니다.","spirit.faith.paragraph1":"악보를 깊이 읽고 작품의 뜻을 이해하며,\n맡은 파트와 무대의 역할에 책임을 다합니다.","spirit.faith.paragraph2":"음악으로 배운 집중과 성실, 배려와 책임이\n일상에서도 좋은 기준으로 이어지도록 돕습니다.","spirit.learning.0.title":"먼저 듣는 사람으로 자랍니다","spirit.learning.1.title":"음악에 담긴 뜻을 배웁니다","spirit.learning.2.title":"공동체 안에서 나의 소리를 찾습니다","spirit.learning.3.title":"한 음과 한 약속을 소중히 여깁니다","spirit.learning.4.title":"음악과 마음을 세상과 나눕니다","spirit.manifesto.label0":"합창의 기본을 배웁니다","spirit.manifesto.label1":"서로 듣는 법을 배웁니다","spirit.manifesto.label2":"무대에서 완성합니다","spirit.manifesto.label3":"삶으로 이어갑니다","spirit.spiritHero.text2":"함께 노래하며","spirit.spiritHero.text3":"사랑과 나눔을","spirit.community.closing":"혼자 부르면 한 사람의 소리입니다.\n서로 듣고 맞추면 화음이 됩니다.\n함께 책임질 때 공동체가 됩니다.","spirit.content.hero.body":"좋은 음악을 향한 태도와 공동체의 가치를\n매주 연습과 공연에서 배우고 이어갑니다.","spirit.spiritHero.text10":"","spirit.content.motet.body":"서로 다른 음색과 역할을 존중하며\n하나의 작품을 완성합니다.\n각자의 개성을 살리면서 같은 목적을 향해\n함께 나아가는 공동체를 만들어 갑니다.","spirit.faithSection.text1":"음악을 통해","spirit.faithSection.text2":"","spirit.faithSection.text3":"세대를","spirit.faithSection.text4":"이어","spirit.faithSection.text5":"갑니다.","spirit.motetMeaning.text1":"","spirit.motetMeaning.text2":"서로 다른 ","spirit.motetMeaning.text3":"목소리","spirit.motetMeaning.text4":"가","spirit.motetMeaning.text5":"하나의 음악을","spirit.motetMeaning.text6":"만듭니다.","spirit.content.motet.quote":"전통을 배우고 부르는 데서 나아가\n오늘의 청소년이 삶으로 이어가도록 합니다.","spirit.valuesSection.text6":"네 가지 원칙을 연습과 공연, 공동체에서 함께 지켜갑니다.","spirit.content.values.0.title":"작품에 충실한 음악","spirit.content.values.1.title":"교회음악의 전통과 영성","spirit.content.values.2.title":"함께 부르는 공동체","spirit.content.values.3.title":"다음 세대를 위한 교육","spirit.educationSection.text1":"합창을 통해 경험하는","spirit.educationSection.text5":"듣고 이해하며 함께 조율합니다. 일상의 약속을 지키며 성장합니다.","spirit.content.cta.supportLabel":"후원 안내","spirit.content.manifesto.0.body":"호흡, 발성, 음정, 리듬, 딕션과 앙상블의 기본을 체계적으로 익힙니다.\n자신의 목소리를 이해하고 함께 어울리는 소리의 기초를 세웁니다.","spirit.content.manifesto.1.body":"자신의 소리뿐 아니라 옆 사람과 다른 파트의 소리를 듣습니다.\n서로의 호흡과 음색을 살피며 균형과 조화를 배웁니다.","spirit.content.manifesto.2.body":"연습을 통해 준비한 음악을 공연에서 함께 표현합니다.\n무대에서 맡은 역할을 끝까지 해내며 집중력과 책임감을 경험합니다.","spirit.content.manifesto.3.body":"음악을 대하는 성실함과 공동체 안에서 배운 태도를 삶으로 이어갑니다.\n서로를 존중하고 약속을 지키며 함께 살아가는 힘을 키웁니다.","spirit.content.values.0.summary":"한 음을 소중히 대합니다","spirit.content.values.1.summary":"깊이 듣고 마음을 돌아봅니다","spirit.content.values.2.summary":"우리의 울림을 먼저 듣습니다","spirit.content.values.3.summary":"음악으로 삶을 세웁니다","spirit.content.values.0.description":"악보에 담긴 음과 말, 작곡가의 뜻을 존중합니다.\n한 음을 소중히 읽고 작품의 의미를 이해하며\n자신의 소리로 표현하는 법을 배웁니다.","spirit.content.values.1.description":"찬송과 교회음악의 전통을 통해\n작품에 대한 존중과 절제, 음악의 깊이를 배웁니다.\n음악으로 마음과 삶을 돌아보는 태도를 익힙니다.","spirit.content.values.2.description":"합창은 혼자 완성할 수 없는 예술입니다.\n서로의 호흡과 소리를 듣고 자신의 역할을 조율하며\n배려와 협력으로 하나의 음악을 만듭니다.","spirit.content.values.3.description":"음악적 기량과 함께 성실함과 책임감을 키웁니다.\n타인을 존중하고 서로 다른 문화를 이해하며\n더 넓은 세계를 바라보는 시야를 넓혀 갑니다.","spirit.spiritHero.text4":"실천","spirit.spiritHero.text5":"합니다.","spirit.spiritHero.english2":"SPIRIT","spirit.valuesSection.text5":"태도","spirit.spiritManifesto.text2":"","spirit.spiritManifesto.text3":"경청과 소통","spirit.spiritManifesto.text4":"을"},"desktop":{"spirit.closingCta.text1":"함께 만들어 갈","spirit.closingCta.text4":"참여해 주세요.","spirit.spiritHero.text2":"함께 노래하며","spirit.spiritHero.text3":"사랑과 나눔을","spirit.spiritHero.text4":"실천","spirit.spiritHero.text5":"합니다.","spirit.faithSection.text1":"음악을 통해","spirit.faithSection.text2":"","spirit.faithSection.text3":"세대를","spirit.faithSection.text4":"이어","spirit.faithSection.text5":"갑니다.","spirit.spiritHero.english2":"SPIRIT","spirit.valuesSection.text5":"태도","spirit.spiritManifesto.text1":"노래하며","spirit.spiritManifesto.text2":"","spirit.spiritManifesto.text3":"경청과 소통","spirit.spiritManifesto.text4":"을","spirit.spiritManifesto.text5":"배웁니다.","spirit.heritageTimeline.text1":"시간은 흘러도","spirit.heritageTimeline.text3":"이어집니다."}},"textStyles":{"desktop":{"spirit.closingCta.text1":{"runs":[{"end":8,"start":0,"style":{"fontSize":50}}],"text":"함께 만들어 갈"},"spirit.closingCta.text4":{"runs":[{"end":8,"start":0,"style":{"fontSize":60,"fontStyle":"normal","fontWeight":700,"textDecoration":"none"}}],"text":"참여해 주세요."},"spirit.spiritHero.text2":{"runs":[{"end":7,"start":0,"style":{"fontSize":60}}],"text":"함께 노래하며"},"spirit.spiritHero.english2":{"runs":[{"end":6,"start":0,"style":{"color":"#fcfaf5","fontStyle":"italic","fontWeight":400,"textDecoration":"none"}}],"text":"SPIRIT"},"spirit.valuesSection.text5":{"runs":[{"end":2,"start":0,"style":{"color":"#ff601a","fontSize":70,"fontStyle":"normal","fontWeight":700}}],"text":"태도"}}},"textLayouts":{"mobile":{},"tablet":{"spirit.content.cta.body":{"offsetX":9.7,"offsetY":20.7}},"desktop":{"spirit.intro.title":{"offsetX":-18.9,"offsetY":27.7},"spirit.closingCta.text1":{"width":74.6,"offsetX":-5.9,"offsetY":15.2},"spirit.closingCta.text2":{"offsetX":41.9,"offsetY":16.4},"spirit.closingCta.text3":{"offsetX":197.3,"offsetY":-31.6},"spirit.closingCta.text4":{"offsetX":-55.1,"offsetY":-12.3},"spirit.spiritHero.text2":{"offsetX":110.1,"offsetY":-27.6},"spirit.spiritHero.text3":{"offsetX":154.8,"offsetY":-31.5},"spirit.spiritHero.text4":{"width":70.8,"offsetX":-0.6,"offsetY":-32.8},"spirit.spiritHero.text5":{"width":73,"offsetX":136,"offsetY":-101.3},"spirit.motetMeaning.text2":{"offsetX":0,"offsetY":34},"spirit.motetMeaning.text3":{"offsetX":5,"offsetY":38.5},"spirit.motetMeaning.text4":{"offsetX":12.6,"offsetY":34},"spirit.motetMeaning.text5":{"offsetX":-11.5,"offsetY":41.5},"spirit.motetMeaning.text6":{"offsetX":2.7,"offsetY":45.3},"spirit.valuesSection.text4":{"offsetX":-87.1,"offsetY":16.4},"spirit.valuesSection.text5":{"offsetX":238.2,"offsetY":-43.2},"spirit.motetMeaning.english2":{"offsetX":20.4,"offsetY":44.6},"spirit.spiritManifesto.text1":{"offsetX":0,"offsetY":17.8},"spirit.spiritManifesto.text2":{"offsetX":142.4,"offsetY":-50.6},"spirit.spiritManifesto.text3":{"offsetX":-35.2,"offsetY":11.4},"spirit.spiritManifesto.text4":{"offsetX":-42.5,"offsetY":5},"spirit.spiritManifesto.text5":{"offsetX":43.3,"offsetY":-1.3},"spirit.heritageTimeline.text2":{"offsetX":43.4,"offsetY":3.8},"spirit.heritageTimeline.text3":{"offsetX":8.3,"offsetY":3.8}}},"schemaVersion":1}}$snapshot_ko_spirit$::jsonb; r public.site_editor_pages%rowtype; stamp timestamptz;
begin
 perform pg_advisory_xact_lock(hashtextextended('site-editor:spirit',0));
 select * into r from public.site_editor_pages where page_key='spirit' for update;
 if (p->>'version')::bigint=0 then
  if found then raise exception 'Document ko_spirit was created concurrently; update refused'; end if;
 elsif not found or r.version<>(p->>'version')::bigint or r.draft is distinct from p->'oldDraft' or r.published is distinct from p->'oldPublished' then
  raise exception 'Document ko_spirit changed concurrently; update refused';
 end if;
 perform public.validate_site_editor_document(p->'next');
 if p->'next'->'deviceCopy'->'desktop' is distinct from r.draft->'deviceCopy'->'desktop' or p->'next'->'textStyles'->'desktop' is distinct from r.draft->'textStyles'->'desktop' or p->'next'->'textLayouts'->'desktop' is distinct from r.draft->'textLayouts'->'desktop' then raise exception 'Korean desktop must remain intact'; end if;
 if (p->>'version')::bigint>0 and ((p->'next') - 'deviceCopy' - 'textStyles' - 'textLayouts') is distinct from (r.draft - 'deviceCopy' - 'textStyles' - 'textLayouts') then raise exception 'Unrelated settings changed'; end if;
 if r.published is not null and not exists(select 1 from public.site_editor_revisions where page_key='spirit' and document=r.published) then
  insert into public.site_editor_revisions(page_key,document,published_at,published_by) values('spirit',r.published,coalesce(r.published_at,clock_timestamp()),null);
 end if;
 stamp:=clock_timestamp();
 insert into public.site_editor_pages(page_key,draft,published,version,updated_at,published_at,updated_by) values('spirit',p->'next',p->'next',(p->>'version')::bigint+2,stamp,stamp,null)
 on conflict(page_key) do update set draft=excluded.draft,published=excluded.published,version=excluded.version,updated_at=excluded.updated_at,published_at=excluded.published_at,updated_by=null;
 insert into public.site_editor_revisions(page_key,document,published_at,published_by) values('spirit',p->'next',stamp,null);
end;
