declare p jsonb := $snapshot_ko_members${"version":3,"oldDraft":{"copy":{},"appearance":{},"deviceCopy":{"desktop":{"members.membersArchiveExperience.text1":"합창단 단원 아카이브","members.membersArchiveExperience.text2":""}},"textStyles":{"desktop":{"members.membersArchiveExperience.text1":{"runs":[{"end":11,"start":0,"style":{"color":"#68233a","fontFamily":"arita-buri"}}],"text":"합창단 단원 아카이브"}}},"schemaVersion":1},"oldPublished":{"copy":{},"appearance":{},"deviceCopy":{"desktop":{"members.membersArchiveExperience.text1":"합창단 단원 아카이브","members.membersArchiveExperience.text2":""}},"textStyles":{"desktop":{"members.membersArchiveExperience.text1":{"runs":[{"end":11,"start":0,"style":{"color":"#68233a","fontFamily":"arita-buri"}}],"text":"합창단 단원 아카이브"}}},"schemaVersion":1},"next":{"copy":{},"appearance":{},"deviceCopy":{"desktop":{"members.membersArchiveExperience.text1":"합창단 단원 아카이브","members.membersArchiveExperience.text2":""},"mobile":{"members.membersArchiveExperience.text1":"합창단 단원 아카이브","members.membersArchiveExperience.text2":""},"tablet":{"members.membersArchiveExperience.text1":"합창단 단원 아카이브","members.membersArchiveExperience.text2":""}},"textStyles":{"desktop":{"members.membersArchiveExperience.text1":{"runs":[{"end":11,"start":0,"style":{"color":"#68233a","fontFamily":"arita-buri"}}],"text":"합창단 단원 아카이브"}}},"schemaVersion":1}}$snapshot_ko_members$::jsonb; r public.site_editor_pages%rowtype; stamp timestamptz;
begin
 perform pg_advisory_xact_lock(hashtextextended('site-editor:members',0));
 select * into r from public.site_editor_pages where page_key='members' for update;
 if (p->>'version')::bigint=0 then
  if found then raise exception 'Document ko_members was created concurrently; update refused'; end if;
 elsif not found or r.version<>(p->>'version')::bigint or r.draft is distinct from p->'oldDraft' or r.published is distinct from p->'oldPublished' then
  raise exception 'Document ko_members changed concurrently; update refused';
 end if;
 perform public.validate_site_editor_document(p->'next');
 if p->'next'->'deviceCopy'->'desktop' is distinct from r.draft->'deviceCopy'->'desktop' or p->'next'->'textStyles'->'desktop' is distinct from r.draft->'textStyles'->'desktop' or p->'next'->'textLayouts'->'desktop' is distinct from r.draft->'textLayouts'->'desktop' then raise exception 'Korean desktop must remain intact'; end if;
 if (p->>'version')::bigint>0 and ((p->'next') - 'deviceCopy' - 'textStyles' - 'textLayouts') is distinct from (r.draft - 'deviceCopy' - 'textStyles' - 'textLayouts') then raise exception 'Unrelated settings changed'; end if;
 if r.published is not null and not exists(select 1 from public.site_editor_revisions where page_key='members' and document=r.published) then
  insert into public.site_editor_revisions(page_key,document,published_at,published_by) values('members',r.published,coalesce(r.published_at,clock_timestamp()),null);
 end if;
 stamp:=clock_timestamp();
 insert into public.site_editor_pages(page_key,draft,published,version,updated_at,published_at,updated_by) values('members',p->'next',p->'next',(p->>'version')::bigint+2,stamp,stamp,null)
 on conflict(page_key) do update set draft=excluded.draft,published=excluded.published,version=excluded.version,updated_at=excluded.updated_at,published_at=excluded.published_at,updated_by=null;
 insert into public.site_editor_revisions(page_key,document,published_at,published_by) values('members',p->'next',stamp,null);
end;
